class RingBuffer:
    def push(self, item):
        if self.size == self.capacity:
            self.dropped += 1
            return False
        self.buf[self.head] = item
        self.head = (self.head + 1) % self.capacity
        self.size += 1
        if self.size > self.max_size:
            self.max_size = self.size
        return True

    def pop(self):
        if self.size == 0:
            return None
        item = self.buf[self.tail]
        self.tail = (self.tail + 1) % self.capacity
        self.size -= 1
        return item
